'From Squeak6.0 of 8 June 2026 [latest update: #22156] on 24 July 2026 at 6:31:37 pm'!"Change Set:		TheWorldMainDockingBar-listWindowsOn-translatedDate:			24 July 2026Author:			Masashi UmezawaAdded translated to list windows menu"!!TheWorldMainDockingBar methodsFor: 'submenu - windows' stamp: 'mu 7/24/2026 18:31'!listWindowsOn: menu	| windows |	menu		addLine;		add: 'Collapse all windows' target: (Project current world) selector: #collapseAllWindows;		addItem: [:item | item 			contents: 'Find Workspace...' translated;			target: self;			selector: #findWorkspace];		addLine;		add: 'Close all windows' target: self selector: #closeAllWindowsUnsafe;		addItem: [:item | item			contents: 'Close all windows without changes' translated;			target: self;			icon: MenuIcons smallBroomIcon;			selector: #closeAllWindows];		add: 'Close all windows but workspaces' target: self selector: #closeAllWindowsButWorkspaces;		addLine.						windows := self allVisibleWindows sorted: [:winA :winB |		((winA model isNil or: [winB model isNil]) or: [winA model name = winB model name])			ifTrue: [winA label < winB label]			ifFalse: [winA model name < winB model name]].	windows ifEmpty: [ 		menu addItem: [ :item | 			item				contents: 'No Windows' translated;				isEnabled: false ] ].	windows do: [ :each |		| windowColor |		windowColor := (each model respondsTo: #windowColorToUse)			ifTrue: [each model windowColorToUse]			ifFalse: [UserInterfaceTheme current get: #uniformWindowColor for: Model]. 		menu addItem: [ :item |			item 				contents: (self windowMenuItemLabelFor: each);				icon: (self colorIcon: windowColor);				target: each;				selector: #comeToFront;				subMenuUpdater: self				selector: #windowMenuFor:on:				arguments: { each };				action: [ each beKeyWindow; expand ] ] ].! !